import React, { useEffect, useState } from "react";
import axios from "axios";

function SmartPlanner() {
  const userId = localStorage.getItem("user_id");
  const [plans, setPlans] = useState([]);

  useEffect(() => {
    axios
      .get(`http://127.0.0.1:8000/smart-plan-advanced/${userId}`)
      .then((res) => setPlans(res.data.plan));
  }, [userId]);

  return (
    <div>
      <h2 style={{ color: "#7b1fa2" }}>Smart Planner 🚀</h2>
      <h3>
       📊 Total Tasks Today: {
       plans.filter(p => p.date === new Date().toISOString().split("T")[0]).length
       }
</h3>
      {plans.map((p, i) => (
        <div key={i} style={card}>
          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <strong>{p.date}</strong>
            <span style={badge(p.priority)}>{p.priority}</span>
          </div>

          <p>{p.task}</p>

          <div style={{ fontSize: "14px", color: "#555" }}>
            ⏱ Study Time: {p.hours} hrs
          </div>
        </div>
      ))}
    </div>
  );
}

const card = {
  background: "#fff",
  padding: "16px",
  borderRadius: "12px",
  marginBottom: "12px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
};

const badge = (priority) => ({
  padding: "4px 10px",
  borderRadius: "8px",
  background:
    priority.includes("High") ? "#ff5252" :
    priority.includes("Medium") ? "#ff9800" :
    "#4caf50",
  color: "#fff",
  fontSize: "12px"
});

export default SmartPlanner;
